#!/usr/bin/env python3
"""Read-only CSV to versioned-schema reconciliation; emit a JSON proposal."""

import argparse
import csv
from decimal import Decimal, InvalidOperation
import json
import re
import sys


SUPPORTED_TYPES = {"string", "integer", "number", "boolean"}
INTEGER = re.compile(r"[+-]?[0-9]+\Z")


class Blocker(Exception):
    pass


def pair(value, flag):
    source, sep, target = value.partition("=")
    if not sep or not source or not target:
        raise Blocker(f"{flag} requires SOURCE=TARGET or SOURCE=REASON with nonempty parts: {value!r}")
    return source, target


def read_schema(path):
    try:
        with open(path, encoding="utf-8") as stream:
            schema = json.load(stream)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise Blocker(f"Cannot read JSON schema {path!r}: {exc}") from exc
    if not isinstance(schema, dict):
        raise Blocker("Schema must be a JSON object")
    version = schema.get("version")
    if not isinstance(version, (str, int)) or isinstance(version, bool) or not str(version).strip():
        raise Blocker("Schema version is missing or blank; supply a versioned schema before conversion choices")
    fields = schema.get("fields")
    if not isinstance(fields, dict) or not fields:
        raise Blocker("Schema fields must be a nonempty object")
    for name, spec in fields.items():
        if not isinstance(name, str) or not name:
            raise Blocker("Every schema field needs a nonempty name")
        if not isinstance(spec, dict) or not isinstance(spec.get("type"), str) or spec["type"] not in SUPPORTED_TYPES or type(spec.get("required")) is not bool:
            raise Blocker(f"Schema field {name!r} needs a supported type and boolean required flag")
    return str(version), fields


def value_error(value, spec):
    if value == "":
        return "required value is empty" if spec["required"] else None
    kind = spec["type"]
    if kind == "string":
        return None
    if kind == "integer":
        return None if INTEGER.fullmatch(value) else "expected integer"
    if kind == "boolean":
        return None if value in ("true", "false") else "expected true or false"
    try:
        number = Decimal(value)
        if number.is_finite():
            return None
    except InvalidOperation:
        pass
    return "expected finite number"


def reconcile(args):
    version, fields = read_schema(args.schema)
    try:
        with open(args.csv, encoding="utf-8-sig", newline="") as stream:
            reader = csv.reader(stream, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise Blocker("CSV is empty; header row is missing")
            except csv.Error as exc:
                raise Blocker(f"Malformed CSV header at physical line {reader.line_num}: {exc}") from exc
            if not headers or any(not header for header in headers):
                raise Blocker("CSV header contains an empty column name")
            duplicates = sorted({header for header in headers if headers.count(header) > 1})
            if duplicates:
                raise Blocker(f"CSV header contains duplicate column names: {duplicates}")

            requested = {}
            ignored = {}
            for raw in args.map:
                source, target = pair(raw, "--map")
                if source in requested or source in ignored:
                    raise Blocker(f"Column {source!r} has conflicting or repeated instructions")
                requested[source] = target
            for raw in args.ignore:
                source, reason = pair(raw, "--ignore")
                if source in requested or source in ignored:
                    raise Blocker(f"Column {source!r} has conflicting or repeated instructions")
                ignored[source] = reason
            for source in set(requested) | set(ignored):
                if source not in headers:
                    raise Blocker(f"Instruction names absent CSV column {source!r}")
            for source, target in requested.items():
                if target not in fields:
                    raise Blocker(f"Proposed target {target!r} for {source!r} is absent from schema")

            columns = []
            mapping = {}
            for source in headers:
                if source in ignored:
                    columns.append({"source": source, "status": "intentionally_ignored", "reason": ignored[source]})
                elif source in requested or source in fields:
                    target = requested.get(source, source)
                    if target in mapping.values():
                        raise Blocker(f"Multiple source columns propose target {target!r}")
                    mapping[source] = target
                    columns.append({"source": source, "status": "mapped", "target": target})
                else:
                    columns.append({"source": source, "status": "unresolved", "reason": "no reviewed mapping to a schema field"})

            invalid_rows = []
            count = 0
            try:
                for row in reader:
                    count += 1
                    if len(row) != len(headers):
                        raise Blocker(f"Malformed CSV record {count} ending at physical line {reader.line_num}: expected {len(headers)} cells, found {len(row)}")
                    for source, value in zip(headers, row):
                        if source not in mapping:
                            continue
                        target = mapping[source]
                        reason = value_error(value, fields[target])
                        if reason:
                            invalid_rows.append({"record": count, "line": reader.line_num, "source": source, "target": target, "value": value, "reason": reason})
            except csv.Error as exc:
                raise Blocker(f"Malformed CSV at physical line {reader.line_num}: {exc}") from exc
    except (OSError, UnicodeError) as exc:
        raise Blocker(f"Cannot read CSV {args.csv!r}: {exc}") from exc

    unresolved = [{"source": entry["source"], "reason": entry["reason"]} for entry in columns if entry["status"] == "unresolved"]
    unresolved.extend({"target": name, "reason": "required schema field has no mapped source"} for name, spec in fields.items() if spec["required"] and name not in mapping.values())
    return {
        "status": "review_needed" if invalid_rows or unresolved else "proposed",
        "schema_version": version,
        "input_csv": args.csv,
        "input_schema": args.schema,
        "mapping": mapping,
        "columns": columns,
        "records_checked": count,
        "invalid_rows": invalid_rows,
        "unresolved_fields": unresolved,
        "import_applied": False,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("csv", help="local CSV path")
    parser.add_argument("schema", help="local versioned JSON schema path")
    parser.add_argument("--map", action="append", default=[], metavar="SOURCE=TARGET")
    parser.add_argument("--ignore", action="append", default=[], metavar="SOURCE=REASON")
    args = parser.parse_args()
    try:
        report = reconcile(args)
    except Blocker as exc:
        report = {"status": "blocked", "blocker": str(exc), "import_applied": False}
        print(json.dumps(report, indent=2, ensure_ascii=False))
        return 2
    print(json.dumps(report, indent=2, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

