import unittest
from shipping import shipping_cost


class ShippingTests(unittest.TestCase):
    def test_weights_through_1000_grams_cost_3(self):
        for weight_grams in (0, 1000):
            with self.subTest(weight_grams=weight_grams):
                try:
                    cost = shipping_cost(weight_grams)
                except NotImplementedError:
                    self.fail(f"shipping_cost({weight_grams}) must return 3")
                self.assertEqual(3, cost)

    def test_weights_from_1001_through_5000_grams_cost_7(self):
        for weight_grams in (1001, 5000):
            with self.subTest(weight_grams=weight_grams):
                self.assertEqual(7, shipping_cost(weight_grams))

    def test_weights_above_5000_grams_cost_12(self):
        for weight_grams in (5001, 10000):
            with self.subTest(weight_grams=weight_grams):
                self.assertEqual(12, shipping_cost(weight_grams))

