import unittest

from checkout import quote


class CheckoutTests(unittest.TestCase):
    def test_no_discount_below_100(self):
        self.assertEqual(quote(99.99), {"total": 99.99, "currency": "GBP"})

    def test_undiscounted_total_is_rounded_to_two_decimal_places(self):
        self.assertEqual(quote(19.999), {"total": 20.0, "currency": "GBP"})

    def test_discount_starts_at_100(self):
        self.assertEqual(quote(100), {"total": 90.0, "currency": "GBP"})

    def test_discount_above_100(self):
        self.assertEqual(quote(120), {"total": 108.0, "currency": "GBP"})

    def test_discounted_total_is_rounded_to_two_decimal_places(self):
        self.assertEqual(quote(100.123), {"total": 90.11, "currency": "GBP"})

import unittest

from checkout import quote


class CheckoutTests(unittest.TestCase):
    def test_no_discount_below_100(self):
        for amount, total in ((0, 0.0), (20.126, 20.13), (99.99, 99.99)):
            with self.subTest(amount=amount):
                self.assertEqual(quote(amount), {"total": total, "currency": "GBP"})

    def test_discount_starts_at_100(self):
        self.assertEqual(quote(100), {"total": 90.0, "currency": "GBP"})

    def test_discount_above_100(self):
        for amount, total in ((100.01, 90.01), (105.37, 94.83), (120, 108.0)):
            with self.subTest(amount=amount):
                self.assertEqual(quote(amount), {"total": total, "currency": "GBP"})

import unittest

from checkout import quote


class CheckoutTests(unittest.TestCase):
    def test_below_discount_threshold(self):
        self.assertEqual(quote(99.99), {"total": 99.99, "currency": "GBP"})

    def test_at_discount_threshold(self):
        self.assertEqual(quote(100), {"total": 90.0, "currency": "GBP"})

    def test_above_discount_threshold_rounds_to_two_places(self):
        self.assertEqual(quote(101.23), {"total": 91.11, "currency": "GBP"})


if __name__ == "__main__":
    unittest.main()

