tools/reconcile-import-schema/scripts/re.content:
#!/usr/bin/env python3
"""Read-only reconciliation of a CSV against a versioned local JSON schema."""

import argparse
import csv
from decimal import Decimal, InvalidOperation
import json
import re
import sys


INTEGER = re.compile(r"[+-]?[0-9]+\Z")
SUPPORTED_TYPES = {"string", "integer", "number", "boolean"}


class Blocker(Exception):
    pass


def validate_csv_lexing(source):
    """Reject quote placement that csv.reader(strict=True) still accepts."""
    state = "field_start"
    last_line = 0
    for line_number, line in enumerate(source, start=1):
        last_line = line_number
        if "\0" in line:
            raise Blocker(f"CSV contains a NUL character at physical line {line_number}.")
        position = 0
        while position < len(line):
            char = line[position]
            if state == "quoted":
                if char == '"':
                    if position + 1 < len(line) and line[position + 1] == '"':
                        position += 1
                    else:
                        state = "after_quote"
            elif char == ',':
                state = "field_start"
            elif char in "\r\n":
                state = "field_start"
            elif state == "field_start" and char == '"':
                state = "quoted"
            elif state == "unquoted" and char == '"':
                raise Blocker(f"CSV has a quote inside an unquoted field at physical line {line_number}.")
            elif state == "after_quote":
                raise Blocker(f"CSV has text after a closing quote at physical line {line_number}.")
            else:
                state = "unquoted"
            position += 1
    if state == "quoted":
        raise Blocker(f"CSV has an unclosed quoted field at physical line {last_line}.")
    source.seek(0)


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Blocker(f"Schema has duplicate JSON key {key!r}.")
        result[key] = value
    return result


def load_schema(path):
    try:
        with open(path, encoding="utf-8-sig") as source:
            schema = json.load(source, object_pairs_hook=unique_object)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise Blocker(f"Cannot read schema {path!r}: {error}") from error
    if not isinstance(schema, dict):
        raise Blocker("Schema root must be a JSON object.")

    version = schema.get("version")
    if version is None or version == "":
        return None, None
    if isinstance(version, bool) or not isinstance(version, (str, int)) or not str(version).strip():
        raise Blocker("Schema version must be a nonempty string or integer.")

    has_fields = "fields" in schema
    has_properties = "properties" in schema
    if has_fields == has_properties:
        raise Blocker("Schema must contain exactly one of 'fields' or 'properties'.")
    field_definitions = schema["fields" if has_fields else "properties"]
    if not isinstance(field_definitions, dict):
        raise Blocker("Schema fields/properties must be an object.")

    if has_properties:
        required = schema.get("required", [])
        if not isinstance(required, list) or any(not isinstance(name, str) for name in required):
            raise Blocker("Schema 'required' must be an array of field names.")
        if len(set(required)) != len(required):
            raise Blocker("Schema 'required' contains duplicate field names.")
        unknown = sorted(set(required) - set(field_definitions))
        if unknown:
            raise Blocker(f"Schema 'required' names unknown fields: {unknown}.")
        required = set(required)

    fields = {}
    for name, definition in field_definitions.items():
        if not name or not isinstance(definition, dict):
            raise Blocker(f"Schema field {name!r} must have a nonempty name and object definition.")
        field_type = definition.get("type")
        if not isinstance(field_type, str) or field_type not in SUPPORTED_TYPES:
            raise Blocker(f"Schema field {name!r} has missing or unsupported type {field_type!r}.")
        if has_fields:
            field_required = definition.get("required")
            if not isinstance(field_required, bool):
                raise Blocker(f"Schema field {name!r} must declare boolean 'required'.")
        else:
            field_required = name in required
        fields[name] = {"type": field_type, "required": field_required}
    return str(version), fields


def parse_directives(args, headers, fields):
    explicit = {}
    ignored = set()
    for item in args.map:
        if "=" not in item:
            raise Blocker(f"Invalid --map {item!r}; use SOURCE=FIELD.")
        source, target = item.split("=", 1)
        if source not in headers:
            raise Blocker(f"--map source column {source!r} is absent from the CSV header.")
        if target not in fields:
            raise Blocker(f"--map target field {target!r} is absent from the schema.")
        if source in explicit and explicit[source] != target:
            raise Blocker(f"Source column {source!r} has conflicting --map targets.")
        explicit[source] = target
    for source in args.ignore:
        if source not in headers:
            raise Blocker(f"--ignore source column {source!r} is absent from the CSV header.")
        if source in explicit:
            raise Blocker(f"Source column {source!r} is both mapped and ignored.")
        ignored.add(source)
    return explicit, ignored


def build_mapping(headers, fields, explicit, ignored):
    mapping = []
    used_targets = {}
    for source in headers:
        if source in ignored:
            mapping.append({"source_column": source, "status": "intentionally_ignored"})
            continue
        target = explicit.get(source, source if source in fields else None)
        if target is None:
            mapping.append({"source_column": source, "status": "unresolved"})
            continue
        if target in used_targets:
            raise Blocker(
                f"Source columns {used_targets[target]!r} and {source!r} both map to target field {target!r}."
            )
        used_targets[target] = source
        mapping.append({
            "source_column": source,
            "status": "mapped",
            "target_field": target,
            "type": fields[target]["type"],
            "required": fields[target]["required"],
            "basis": "explicit" if source in explicit else "exact_header_match",
        })
    unresolved = [
        {"kind": "source_column", "name": item["source_column"]}
        for item in mapping if item["status"] == "unresolved"
    ]
    unresolved.extend(
        {"kind": "required_target_field", "name": name}
        for name, definition in fields.items()
        if definition["required"] and name not in used_targets
    )
    return mapping, unresolved


def valid_value(value, field_type):
    if field_type == "string":
        return True
    if field_type == "integer":
        return bool(INTEGER.fullmatch(value))
    if field_type == "boolean":
        return value.lower() in {"true", "false"}
    try:
        return Decimal(value).is_finite()
    except InvalidOperation:
        return False


def inspect_row(row, headers, mapping, record_number, first_line, last_line):
    issues = []
    if len(row) != len(headers):
        issues.append({"code": "column_count", "expected": len(headers), "actual": len(row)})
    else:
        for value, item in zip(row, mapping):
            if item["status"] != "mapped":
                continue
            stripped = value.strip()
            if not stripped:
                if item["required"]:
                    issues.append({
                        "code": "required_value_missing",
                        "source_column": item["source_column"],
                        "target_field": item["target_field"],
                    })
            elif not valid_value(stripped, item["type"]):
                issues.append({
                    "code": "invalid_type",
                    "source_column": item["source_column"],
                    "target_field": item["target_field"],
                    "expected_type": item["type"],
                })
    if not issues:
        return None
    return {
        "record_number": record_number,
        "physical_lines": [first_line, last_line],
        "issues": issues,
    }


def report(args):
    result = {
        "status": "blocked",
        "csv": args.csv,
        "schema": args.schema,
        "schema_version": None,
        "mapping": [],
        "unresolved_fields": [],
        "invalid_rows": [],
        "data_records_checked": 0,
        "blockers": [],
    }
    try:
        with open(args.csv, encoding="utf-8-sig", newline="") as source:
            validate_csv_lexing(source)
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise Blocker("CSV has no header record.")
            except csv.Error as error:
                raise Blocker(f"CSV header is malformed at physical line {reader.line_num}: {error}") from error
            if not headers or any(not name.strip() for name in headers):
                raise Blocker("CSV header contains an empty column name.")
            if len(headers) != len(set(headers)):
                raise Blocker("CSV header contains duplicate column names.")

            version, fields = load_schema(args.schema)
            result["schema_version"] = version
            if version is None:
                result["status"] = "needs_clarification"
                result["mapping"] = [
                    {"source_column": name, "status": "unresolved", "reason": "schema_version_missing"}
                    for name in headers
                ]
                result["unresolved_fields"] = [
                    {"kind": "source_column", "name": name} for name in headers
                ]
                result["blockers"] = ["Schema version is missing; confirm a versioned schema before mapping or conversion choices."]
                return result

            explicit, ignored = parse_directives(args, headers, fields)
            mapping, unresolved = build_mapping(headers, fields, explicit, ignored)
            result["mapping"] = mapping
            result["unresolved_fields"] = unresolved
            previous_line = reader.line_num
            try:
                for record_number, row in enumerate(reader, start=2):
                    first_line = previous_line + 1
                    last_line = reader.line_num
                    previous_line = last_line
                    result["data_records_checked"] += 1
                    invalid = inspect_row(row, headers, mapping, record_number, first_line, last_line)
                    if invalid:
                        result["invalid_rows"].append(invalid)
            except csv.Error as error:
                raise Blocker(f"CSV is malformed at physical line {reader.line_num}: {error}") from error
            result["status"] = "proposed"
    except (OSError, UnicodeError) as error:
        result["blockers"].append(f"Cannot read CSV {args.csv!r}: {error}")
    except Blocker as error:
        result["blockers"].append(str(error))
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--csv", required=True, help="Local CSV path")
    parser.add_argument("--schema", required=True, help="Local versioned JSON schema path")
    parser.add_argument("--map", action="append", default=[], metavar="SOURCE=FIELD")
    parser.add_argument("--ignore", action="append", default=[], metavar="SOURCE")
    args = parser.parse_args()
    result = report(args)
    json.dump(result, sys.stdout, indent=2, ensure_ascii=False)
    sys.stdout.write("\n")
    return {"proposed": 0, "needs_clarification": 2, "blocked": 3}[result["status"]]


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Read local CSV and schema files; print a proposed reconciliation as JSON."""

import argparse
import csv
from decimal import Decimal, InvalidOperation
import io
import json
import re
import sys


INTEGER = re.compile(r"-?(?:0|[1-9][0-9]*)\Z")
NUMBER = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?\Z")
SUPPORTED_TYPES = {"string", "integer", "number", "boolean"}


class Blocked(Exception):
    pass


def fail(message):
    raise Blocked(message)


def parse_assignments(items):
    assignments = {}
    for item in items:
        source, separator, target = item.partition("=")
        if not separator or not source or not target:
            fail(f"Invalid --map {item!r}; expected SOURCE=FIELD")
        if source in assignments:
            fail(f"Source column {source!r} is mapped more than once")
        assignments[source] = target
    return assignments


def read_schema(path):
    try:
        with open(path, encoding="utf-8") as handle:
            schema = json.load(handle)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        fail(f"Cannot read JSON schema {path!r}: {error}")
    if not isinstance(schema, dict):
        fail("Schema must be a JSON object")
    version = schema.get("version")
    if not isinstance(version, str) or not version.strip():
        fail("Schema version is missing; clarify the version before choosing conversions")

    if isinstance(schema.get("fields"), dict):
        shape = "fields"
        fields = schema["fields"]
        root_known = {"version", "fields", "$schema", "title", "description"}
    elif isinstance(schema.get("properties"), dict):
        shape = "properties"
        fields = schema["properties"]
        root_known = {"version", "properties", "required", "$schema", "type", "title", "description"}
        if schema.get("type", "object") != "object":
            fail("Schema with 'properties' must describe an object")
        required = schema.get("required", [])
        if not isinstance(required, list) or any(not isinstance(name, str) for name in required):
            fail("Schema 'required' must be an array of field names")
        unknown_required = sorted(set(required) - set(fields))
        if unknown_required:
            fail(f"Required fields absent from properties: {unknown_required}")
    else:
        fail("Schema needs a 'fields' or 'properties' object")

    if not fields:
        fail("Schema has no fields")
    normalized = {}
    unvalidated = [f"schema.{key}" for key in sorted(set(schema) - root_known)]
    for name, spec in fields.items():
        if not isinstance(name, str) or not name or not isinstance(spec, dict):
            fail(f"Invalid schema field {name!r}: expected a named object")
        field_type = spec.get("type")
        if not isinstance(field_type, str):
            fail(f"Schema field {name!r} needs a string type")
        if shape == "fields":
            is_required = spec.get("required", False)
            if not isinstance(is_required, bool):
                fail(f"Schema field {name!r} has a non-boolean required value")
            known = {"type", "required", "title", "description"}
        else:
            is_required = name in required
            known = {"type", "title", "description"}
        normalized[name] = {"type": field_type, "required": is_required}
        unvalidated.extend(f"{name}.{key}" for key in sorted(set(spec) - known))
        if field_type not in SUPPORTED_TYPES:
            unvalidated.append(f"{name}.type ({field_type})")
    return version, normalized, unvalidated


def value_problem(value, field_type, required):
    if value == "":
        return "required value is empty" if required else None
    if field_type == "integer" and not INTEGER.fullmatch(value):
        return "not an integer"
    if field_type == "number":
        if not NUMBER.fullmatch(value):
            return "not a number"
        try:
            Decimal(value)
        except InvalidOperation:
            return "not a number"
    if field_type == "boolean" and value not in {"true", "false"}:
        return "not a boolean (expected true or false)"
    return None


def check_csv_syntax(content):
    """Reject quote placement that csv.reader accepts outside RFC-style CSV."""
    state = "start"
    line = 1
    for index, char in enumerate(content):
        if state == "start":
            if char == '"':
                state = "quoted"
            elif char not in ",\r\n":
                state = "plain"
        elif state == "plain":
            if char == '"':
                fail(f"Malformed CSV at physical line {line}: quote inside an unquoted field")
            if char in ",\r\n":
                state = "start"
        elif state == "quoted":
            if char == '"':
                state = "after_quote"
        elif char == '"':
            state = "quoted"
        elif char in ",\r\n":
            state = "start"
        else:
            fail(f"Malformed CSV at physical line {line}: character after closing quote")
        if char == "\n" or (char == "\r" and content[index:index + 2] != "\r\n"):
            line += 1
    if state == "quoted":
        fail(f"Malformed CSV at physical line {line}: unterminated quoted field")


def reconcile(csv_path, fields, assignments, ignored):
    try:
        handle = open(csv_path, encoding="utf-8-sig", newline="")
    except (OSError, UnicodeError) as error:
        fail(f"Cannot read CSV {csv_path!r}: {error}")
    with handle:
        try:
            content = handle.read()
        except (OSError, UnicodeError) as error:
            fail(f"Cannot read CSV {csv_path!r}: {error}")
        check_csv_syntax(content)
        try:
            reader = csv.reader(io.StringIO(content, newline=""), strict=True)
            headers = next(reader, None)
            if headers is None:
                fail("CSV is empty; no header row")
            if not headers or any(not header for header in headers):
                fail("CSV has an empty header")
            if len(headers) != len(set(headers)):
                fail("CSV has duplicate headers; source columns are ambiguous")
            missing_sources = sorted((set(assignments) | set(ignored)) - set(headers))
            if missing_sources:
                fail(f"Named source columns absent from CSV: {missing_sources}")
            overlap = sorted(set(assignments) & set(ignored))
            if overlap:
                fail(f"Columns both mapped and ignored: {overlap}")
            unknown_targets = sorted(set(assignments.values()) - set(fields))
            if unknown_targets:
                fail(f"Proposed fields absent from schema: {unknown_targets}")

            mapping = []
            unresolved = []
            targets = set()
            for source in headers:
                if source in ignored:
                    continue
                target = assignments.get(source, source if source in fields else None)
                if target is None:
                    unresolved.append(source)
                    continue
                if target in targets:
                    fail(f"More than one source column maps to schema field {target!r}")
                targets.add(target)
                mapping.append({"source": source, "field": target, **fields[target]})

            invalid_rows = []
            row_count = 0
            for row in reader:
                if len(row) != len(headers):
                    fail(f"Malformed CSV at physical line {reader.line_num}: expected {len(headers)} columns, found {len(row)}")
                row_count += 1
                values = dict(zip(headers, row))
                for item in mapping:
                    source, field = item["source"], item["field"]
                    problem = value_problem(values[source], item["type"], item["required"])
                    if problem:
                        invalid_rows.append({"record": row_count, "line": reader.line_num,
                                             "source": source, "field": field,
                                             "value": values[source], "problem": problem})
        except csv.Error as error:
            fail(f"Malformed CSV at physical line {reader.line_num}: {error}")

    unresolved_required = sorted(name for name, spec in fields.items()
                                 if spec["required"] and name not in targets)
    return {"proposed_mapping": mapping, "intentionally_ignored": [h for h in headers if h in ignored],
            "unresolved_source_columns": unresolved, "unresolved_required_fields": unresolved_required,
            "invalid_rows": invalid_rows, "records_read": row_count}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("csv_path")
    parser.add_argument("schema_path")
    parser.add_argument("--map", action="append", default=[], metavar="SOURCE=FIELD")
    parser.add_argument("--ignore", action="append", default=[], metavar="SOURCE")
    args = parser.parse_args()
    report = {"status": "blocked", "applied_import": False}
    try:
        assignments = parse_assignments(args.map)
        if len(args.ignore) != len(set(args.ignore)):
            fail("An ignored source column was named more than once")
        version, fields, unvalidated = read_schema(args.schema_path)
        report["schema_version"] = version
        report.update(reconcile(args.csv_path, fields, assignments, set(args.ignore)))
        report["unvalidated_constraints"] = unvalidated
        report["status"] = ("needs_review" if any(report[key] for key in
                            ("invalid_rows", "unresolved_source_columns", "unresolved_required_fields",
                             "unvalidated_constraints")) else "proposed")
    except Blocked as error:
        report["blockers"] = [str(error)]
    print(json.dumps(report, indent=2))
    return 2 if report["status"] == "blocked" else 0


if __name__ == "__main__":
    sys.exit(main())

