#!/usr/bin/env python3
"""Read-only, conservative CSV-to-schema reconciliation using the standard library."""

import argparse
import csv
import json
import re
import sys


INTEGER = re.compile(r"-?(?:0|[1-9][0-9]*)\Z")
NUMBER = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?\Z")


def blocked(message, **context):
    return {"status": "blocked", "blockers": [message], **context}


def load_schema(path):
    try:
        with open(path, encoding="utf-8") as source:
            schema = json.load(source)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        return None, blocked(f"Cannot read schema: {error}")
    if not isinstance(schema, dict):
        return None, blocked("Schema root must be a JSON object.")
    versions = [schema[key] for key in ("version", "schema_version") if key in schema]
    if not versions or any(not isinstance(v, (str, int)) or isinstance(v, bool) or not str(v).strip() for v in versions):
        return None, blocked("Schema version is missing or empty; clarify the target version before conversion choices.")
    if len(versions) == 2 and str(versions[0]) != str(versions[1]):
        return None, blocked("Schema version and schema_version disagree; clarify the target version.")
    version = str(versions[0])
    if "fields" in schema:
        fields = schema["fields"]
        if not isinstance(fields, dict):
            return None, blocked("Schema fields must be an object.")
        required = {name for name, definition in fields.items()
                    if isinstance(definition, dict) and definition.get("required") is True}
    elif "properties" in schema:
        fields = schema["properties"]
        required_list = schema.get("required", [])
        if not isinstance(fields, dict) or not isinstance(required_list, list) or any(not isinstance(x, str) for x in required_list):
            return None, blocked("Schema properties must be an object and required must be a list of field names.")
        required = set(required_list)
    else:
        return None, blocked("Schema must contain a fields or properties object.")
    if any(not isinstance(name, str) or not isinstance(definition, dict) for name, definition in fields.items()):
        return None, blocked("Every schema field must have a name and an object definition.")
    if "fields" in schema and any("required" in definition and not isinstance(definition["required"], bool)
                                  for definition in fields.values()):
        return None, blocked("Every field's required status must be a boolean when declared.")
    if required - fields.keys():
        return None, blocked("Schema marks nonexistent fields as required: " + ", ".join(sorted(required - fields.keys())))
    return (version, fields, required), None


def load_csv(path):
    try:
        with open(path, encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                return None, blocked("CSV is empty; no header row exists.")
            if not headers or any(not header.strip() for header in headers):
                return None, blocked(f"CSV header contains an empty column name at physical line {reader.line_num}.")
            if len(headers) != len(set(headers)):
                duplicates = sorted({name for name in headers if headers.count(name) > 1})
                return None, blocked("CSV header contains duplicate columns: " + ", ".join(duplicates))
            rows = []
            for record_number, cells in enumerate(reader, start=2):
                if len(cells) != len(headers):
                    return None, blocked(
                        f"CSV record {record_number} ending at physical line {reader.line_num} has {len(cells)} cells; expected {len(headers)}."
                    )
                rows.append((record_number, reader.line_num, dict(zip(headers, cells))))
            return (headers, rows), None
    except csv.Error as error:
        return None, blocked(f"Malformed CSV near physical line {reader.line_num}: {error}")
    except (OSError, UnicodeError) as error:
        return None, blocked(f"Cannot read CSV: {error}")


def valid_type(value, declared):
    types = declared if isinstance(declared, list) else [declared]
    if not types or any(not isinstance(item, str) for item in types):
        return None
    for kind in types:
        if kind == "string":
            return True
        if kind == "integer" and INTEGER.fullmatch(value):
            return True
        if kind == "number" and NUMBER.fullmatch(value):
            return True
        if kind == "boolean" and value in ("true", "false"):
            return True
        if kind == "null" and value == "null":
            return True
    if any(kind not in ("string", "integer", "number", "boolean", "null") for kind in types):
        return None
    return False


def reconcile(csv_path, schema_path, requested_maps, requested_ignores):
    schema_data, error = load_schema(schema_path)
    if error:
        return error
    version, fields, required = schema_data
    csv_data, error = load_csv(csv_path)
    if error:
        return {**error, "schema_version": version}
    headers, rows = csv_data
    overrides = {}
    for item in requested_maps:
        if "=" not in item:
            return blocked(f"Invalid --map {item!r}; expected source=target.", schema_version=version)
        source, target = item.split("=", 1)
        if source in overrides:
            return blocked(f"Source column {source!r} has multiple explicit mappings.", schema_version=version)
        overrides[source] = target
    ignores = set(requested_ignores)
    for source in list(overrides) + list(ignores):
        if source not in headers:
            return blocked(f"Specified source column {source!r} is absent from the CSV header.", schema_version=version)
    if ignores & overrides.keys():
        return blocked("A column cannot be both mapped and ignored: " + ", ".join(sorted(ignores & overrides.keys())), schema_version=version)
    for source, target in overrides.items():
        if target not in fields:
            return blocked(f"Proposed target field {target!r} for {source!r} is absent from the schema.", schema_version=version)
    mapping = {source: overrides.get(source, source) for source in headers
               if source not in ignores and (source in overrides or source in fields)}
    if len(mapping.values()) != len(set(mapping.values())):
        return blocked("Multiple source columns map to the same target field.", schema_version=version)
    unresolved = [source for source in headers if source not in ignores and source not in mapping]
    missing_required = sorted(required - set(mapping.values()))
    unvalidated = sorted({target for target in mapping.values()
                          if valid_type("0", fields[target].get("type")) is None})
    invalid_rows = []
    for record_number, physical_line, row in rows:
        issues = [f"Required target {target!r} has no mapped source column" for target in missing_required]
        for source, target in mapping.items():
            value = row[source]
            if target in required and value == "":
                issues.append(f"{source!r} → {target!r}: required value is empty")
            elif value != "" and valid_type(value, fields[target].get("type")) is False:
                issues.append(f"{source!r} → {target!r}: value {value!r} is not {fields[target]['type']!r}")
        if issues:
            invalid_rows.append({"csv_record": record_number, "physical_line_end": physical_line, "issues": issues})
    return {
        "status": "proposed", "schema_version": version,
        "columns": [{"source": source,
                     "disposition": "intentionally_ignored" if source in ignores else "mapped" if source in mapping else "unresolved",
                     **({"target": mapping[source], "type": fields[mapping[source]].get("type"),
                         "required": mapping[source] in required} if source in mapping else {})}
                    for source in headers],
        "missing_required_targets": missing_required,
        "unresolved_columns": unresolved,
        "intentionally_ignored_columns": [source for source in headers if source in ignores],
        "unvalidated_target_types": unvalidated,
        "row_count": len(rows), "invalid_rows": invalid_rows,
        "limitations": ["Only declared scalar types and required values are checked; other schema constraints are not validated."],
        "import_applied": False,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--csv", required=True, help="Local CSV path")
    parser.add_argument("--schema", required=True, help="Local versioned JSON schema path")
    parser.add_argument("--map", action="append", default=[], metavar="SOURCE=TARGET")
    parser.add_argument("--ignore", action="append", default=[], metavar="SOURCE")
    args = parser.parse_args()
    result = reconcile(args.csv, args.schema, args.map, args.ignore)
    print(json.dumps(result, indent=2, ensure_ascii=False))
    return 2 if result["status"] == "blocked" else 0


if __name__ == "__main__":
    sys.exit(main())
